import{_ as r,J as d,b as n,e as s,a8 as i,f as e,L as l,q as t}from"./chunks/framework.BXWQBDlf.js";const b=JSON.parse('{"title":"GR32.Blend.Modes","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32.Blend.Modes","entity":"GR32.Blend.Modes","kind":"Unit","summary":"Provides an extensible blend mode registry service and object-oriented blender class hierarchy for Graphics32.","seealso":["[[GR32_Blend]]","[[Graphics32BlendService]]"],"title":"GR32.Blend.Modes","date":1789495588000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32.Blend.Modes/index.md","filePath":"api/GR32.Blend.Modes/index.md","lastUpdated":1789495588000,"timestamp":1789495588000,"datetime":"2026-09-15T18:06:28.000Z"}'),c={name:"api/GR32.Blend.Modes/index.md"};function p(h,a,G,m,B,u){const o=d("ApiMembers");return n(),s("div",null,[a[0]||(a[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32.Blend.Modes</code> unit provides an object-oriented framework for custom pixel blending modes and compositing algorithms in Graphics32.</p><p>Key features provided by <code>GR32.Blend.Modes</code> include:</p><ul><li><strong>Blender Class Hierarchy</strong>: Base abstract classes <a href="/api/GR32.Blend.Modes/TCustomGraphics32Blender/"><code>TCustomGraphics32Blender</code></a>, <a href="/api/GR32.Blend.Modes/TCustomGraphics32ComponentBlender/"><code>TCustomGraphics32ComponentBlender</code></a>, <a href="/api/GR32.Blend.Modes/TGraphics32ComponentBlender/"><code>TGraphics32ComponentBlender</code></a>, and <a href="/api/GR32.Blend.Modes/TGraphics32SeparableBlender/"><code>TGraphics32SeparableBlender</code></a> for implementing custom blending algorithms.</li><li><strong>Normal Blender</strong>: The default <a href="/api/GR32.Blend.Modes/TGraphics32BlenderNormal/"><code>TGraphics32BlenderNormal</code></a> implementation that delegates standard pixel blending to Graphics32&#39;s fast core routines.</li><li><strong>Adobe / Photoshop Compositing</strong>: <a href="/api/GR32.Blend.Modes/TGraphics32ComponentBlender/"><code>TGraphics32ComponentBlender</code></a> implements the standard Adobe Photoshop separable alpha compositing formula for multi-layer color blending.</li><li><strong>Global Blend Service</strong>: The <a href="/api/GR32.Blend.Modes/Graphics32BlendService"><code>Graphics32BlendService</code></a> singleton and related interfaces (<a href="/api/GR32.Blend.Modes/IGraphics32BlendService"><code>IGraphics32BlendService</code></a>, <a href="/api/GR32.Blend.Modes/IGraphics32BlendGroups"><code>IGraphics32BlendGroups</code></a>, <a href="/api/GR32.Blend.Modes/IGraphics32BlendGroup"><code>IGraphics32BlendGroup</code></a>, <a href="/api/GR32.Blend.Modes/IGraphics32BlendEnumerator"><code>IGraphics32BlendEnumerator</code></a>, <a href="/api/GR32.Blend.Modes/IGraphics32BlendGroupsEnumerator"><code>IGraphics32BlendGroupsEnumerator</code></a>) enable dynamic registration, enumeration, and discovery of blend modes and blend groups across Photoshop, Porter-Duff, and extra blend mode libraries.</li></ul><hr>',5)),e("p",null,[l(o,{type:"members"})]),a[1]||(a[1]=e("h2",{id:"see-also",tabindex:"-1"},[t("See also "),e("a",{class:"header-anchor",href:"#see-also","aria-label":'Permalink to "See also"'},"​")],-1)),a[2]||(a[2]=e("ul",null,[e("li",null,[e("a",{href:"/api/GR32_Blend/"},[e("code",null,"GR32_Blend")])]),e("li",null,[e("a",{href:"/api/GR32.Blend.Modes/Graphics32BlendService"},[e("code",null,"Graphics32BlendService")])])],-1))])}const R=r(c,[["render",p]]);export{b as __pageData,R as default};
